import sys

def solve_sudoku(board):
    # Find an empty cell
    for i in range(9):
        for j in range(9):
            if board[i][j] == '.':
                # Try all digits from 1 to 9
                for num in '123456789':
                    if is_valid(board, i, j, num):
                        board[i][j] = num
                        if solve_sudoku(board):
                            return True
                        board[i][j] = '.'
                return False
    return True

def is_valid(board, row, col, num):
    # Check row
    if num in board[row]:
        return False
    # Check column
    if num in [board[i][col] for i in range(9)]:
        return False
    # Check 3x3 subgrid
    start_row, start_col = 3 * (row // 3), 3 * (col // 3)
    for i in range(3):
        for j in range(3):
            if board[start_row + i][start_col + j] == num:
                return False
    return True

# Read input
board = []
for _ in range(9):
    line = sys.stdin.readline().strip()
    if line:
        row = line.split()
        board.append(row)

# Solve
solve_sudoku(board)

# Print output
for row in board:
    print(' '.join(row))
